<?php
session_start();
if(($_SESSION['logged_in']??false)!==true){http_response_code(401);exit('Please log in.');}
header('Cache-Control: no-store');
if(empty($_SESSION['chat_csrf']))$_SESSION['chat_csrf']=bin2hex(random_bytes(24));
function db():PDO{$p=parse_url(getenv('DATABASE_URL')?:'');if(!$p||empty($p['host'])||empty($p['user'])||empty($p['path']))throw new RuntimeException('Database is not configured');return new PDO('pgsql:host='.$p['host'].';port='.($p['port']??5432).';dbname='.ltrim($p['path'],'/'),urldecode($p['user']),urldecode($p['pass']??''),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);}
function setup(PDO $d):void{$d->exec("CREATE TABLE IF NOT EXISTS app_chat_users (id BIGSERIAL PRIMARY KEY, identity_key VARCHAR(255) UNIQUE NOT NULL, display_name VARCHAR(150) NOT NULL, last_seen TIMESTAMPTZ DEFAULT now()); CREATE TABLE IF NOT EXISTS app_chat_messages(id BIGSERIAL PRIMARY KEY,sender_id BIGINT NOT NULL REFERENCES app_chat_users(id),recipient_id BIGINT NOT NULL REFERENCES app_chat_users(id),body TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now(),read_at TIMESTAMPTZ); CREATE INDEX IF NOT EXISTS chat_msg_pair ON app_chat_messages(sender_id,recipient_id,id); CREATE TABLE IF NOT EXISTS app_chat_calls(id BIGSERIAL PRIMARY KEY,caller_id BIGINT NOT NULL REFERENCES app_chat_users(id),callee_id BIGINT NOT NULL REFERENCES app_chat_users(id),kind VARCHAR(10) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'ringing',created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now()); CREATE TABLE IF NOT EXISTS app_chat_signals(id BIGSERIAL PRIMARY KEY,call_id BIGINT NOT NULL REFERENCES app_chat_calls(id) ON DELETE CASCADE,sender_id BIGINT NOT NULL REFERENCES app_chat_users(id),payload JSONB NOT NULL,created_at TIMESTAMPTZ DEFAULT now());");}
function reply($data,int $status=200):never{header('Content-Type: application/json');http_response_code($status);echo json_encode($data,JSON_UNESCAPED_SLASHES);exit;}
try{
$d=db();setup($d);
// Login implementation must supply a stable, unique authenticated account ID.
$identity=$_SESSION['user_id']??$_SESSION['id']??null;
if($identity===null||!is_scalar($identity)||trim((string)$identity)==='')throw new RuntimeException('Chat requires a stable authenticated user ID in the login session (user_id or id).');
$key='account:'.(string)$identity;
// The login.php users table is the authoritative contact directory.
// Register every account, even if the person has never opened Messages.
// Keep chat IDs stable: existing conversations and calls remain attached to the same IDs.
$d->exec("INSERT INTO app_chat_users(identity_key,display_name,last_seen)
 SELECT 'account:' || id::text,
        initcap(split_part(username,'@',1)),
        NULL
 FROM users
 WHERE TRUE
 ON CONFLICT(identity_key) DO UPDATE
 SET display_name=EXCLUDED.display_name");
$q=$d->prepare('UPDATE app_chat_users SET last_seen=now() WHERE identity_key=? RETURNING id');
$q->execute([$key]);$me=(int)$q->fetchColumn();
if(!$me)throw new RuntimeException('Authenticated account not found in the users directory.');
// Allow message polling and sending in separate requests without a PHP session lock.
$chatCsrf=$_SESSION['chat_csrf'];
session_write_close();
$action=$_GET['action']??'';
if($action){
 if($_SERVER['REQUEST_METHOD']==='POST' && !hash_equals($chatCsrf,(string)($_SERVER['HTTP_X_CSRF_TOKEN']??'')))reply(['error'=>'Security token invalid'],403);
 $input=json_decode(file_get_contents('php://input'),true)??[];$other=(int)($input['user']??$_GET['user']??0);
 $check=function(int $id)use($d,$me){if($id<1||$id===$me)return false;$s=$d->prepare('SELECT 1 FROM app_chat_users WHERE id=?');$s->execute([$id]);return(bool)$s->fetchColumn();};
 if($action==='users'){$s=$d->prepare('SELECT u.id,u.display_name,u.last_seen,(SELECT count(*) FROM app_chat_messages m WHERE m.sender_id=u.id AND m.recipient_id=? AND m.read_at IS NULL) AS unread FROM app_chat_users u WHERE u.id<>? ORDER BY u.display_name, u.id');$s->execute([$me,$me]);reply(['me'=>$me,'users'=>$s->fetchAll()]);}
 if($action==='messages'&&$check($other)){$s=$d->prepare('SELECT id,sender_id,recipient_id,body,created_at,read_at FROM (SELECT * FROM app_chat_messages WHERE (sender_id=? AND recipient_id=?) OR (sender_id=? AND recipient_id=?) ORDER BY id DESC LIMIT 150) x ORDER BY id');$s->execute([$me,$other,$other,$me]);$d->prepare('UPDATE app_chat_messages SET read_at=now() WHERE sender_id=? AND recipient_id=? AND read_at IS NULL')->execute([$other,$me]);reply(['messages'=>$s->fetchAll()]);}
 if($action==='send'&&$check($other)){$body=trim((string)($input['body']??''));if($body===''||mb_strlen($body)>4000)reply(['error'=>'Message must be 1–4000 characters'],422);$s=$d->prepare('INSERT INTO app_chat_messages(sender_id,recipient_id,body) VALUES (?,?,?) RETURNING id');$s->execute([$me,$other,$body]);reply(['ok'=>true,'id'=>$s->fetchColumn()]);}
 if($action==='call'&&$check($other)){$kind=$input['kind']??'';if(!in_array($kind,['audio','video'],true))reply(['error'=>'Invalid call type'],422);$s=$d->prepare("INSERT INTO app_chat_calls(caller_id,callee_id,kind) VALUES (?,?,?) RETURNING id");$s->execute([$me,$other,$kind]);reply(['id'=>(int)$s->fetchColumn()]);}
 if($action==='calls'){$s=$d->prepare("SELECT c.*,u.display_name AS caller_name FROM app_chat_calls c JOIN app_chat_users u ON u.id=c.caller_id WHERE (callee_id=? OR caller_id=?) AND status IN ('ringing','active') AND created_at>now()-interval '2 hours' ORDER BY id DESC LIMIT 10");$s->execute([$me,$me]);reply(['calls'=>$s->fetchAll()]);}
 $call=(int)($input['call']??$_GET['call']??0);
 if(in_array($action,['signal','signals','status'],true)){$s=$d->prepare('SELECT * FROM app_chat_calls WHERE id=? AND (caller_id=? OR callee_id=?)');$s->execute([$call,$me,$me]);$c=$s->fetch();if(!$c)reply(['error'=>'Call not found'],404);
 if($action==='status'){$status=$input['status']??'';if(!in_array($status,['active','ended','declined'],true))reply(['error'=>'Invalid status'],422);if($status==='active'&&(int)$c['callee_id']!==$me)reply(['error'=>'Only recipient may answer'],403);$d->prepare('UPDATE app_chat_calls SET status=?,updated_at=now() WHERE id=?')->execute([$status,$call]);reply(['ok'=>true]);}
 if($action==='signal'){$payload=$input['payload']??null;if(!is_array($payload)||strlen(json_encode($payload))>20000||!in_array($payload['type']??'',['offer','answer','candidate'],true))reply(['error'=>'Invalid signal'],422);$d->prepare('INSERT INTO app_chat_signals(call_id,sender_id,payload) VALUES (?,?,?)')->execute([$call,$me,json_encode($payload)]);reply(['ok'=>true]);}
 $after=max(0,(int)($_GET['after']??0));$s=$d->prepare('SELECT id,payload FROM app_chat_signals WHERE call_id=? AND sender_id<>? AND id>? ORDER BY id LIMIT 100');$s->execute([$call,$me,$after]);$rows=$s->fetchAll();foreach($rows as &$r)$r['payload']=json_decode($r['payload'],true);reply(['signals'=>$rows,'status'=>$c['status']]);}
 reply(['error'=>'Invalid request'],400);
}
}catch(Throwable $e){error_log('Messages: '.$e->getMessage());if(isset($_GET['action']))reply(['error'=>$e->getMessage()==='Chat requires a stable authenticated user ID in the login session (user_id or id).'?$e->getMessage():'Messaging service unavailable'],503);$startupError='Messaging setup needs attention. Check login user ID and PostgreSQL configuration.';}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Messages & Calls</title><style>
*{box-sizing:border-box}body{margin:0;font:14px system-ui,Arial;background:#f6f4f2;color:#2d2522}.app{display:grid;grid-template-columns:300px 1fr;height:100vh;min-height:550px}.side{background:#fff;border-right:1px solid #e9e3df;display:flex;flex-direction:column}.brand{padding:25px 20px 15px;font-size:23px;font-weight:800;color:#422a22}.sub{font-size:12px;font-weight:400;color:#95867e;margin-top:4px}.search{margin:8px 16px 15px;padding:12px;border:1px solid #e6ddd7;border-radius:12px;width:calc(100% - 32px)}.users{overflow:auto;flex:1}.user{display:flex;align-items:center;gap:12px;padding:14px 17px;cursor:pointer;border:0;background:transparent;width:100%;text-align:left}.user:hover,.user.selected{background:#f3eae5}.avatar{background:#eadad1;color:#5d4037;border-radius:50%;width:42px;height:42px;display:grid;place-items:center;font-weight:800;flex-shrink:0}.uname{font-weight:700}.hint{font-size:12px;color:#9a8d86;margin-top:4px}.count{margin-left:auto;border-radius:20px;background:#6d4c41;color:white;padding:3px 7px}.main{display:flex;flex-direction:column;min-width:0}.head{background:white;padding:17px 24px;border-bottom:1px solid #e9e3df;display:flex;align-items:center;gap:12px;min-height:78px}.head strong{font-size:17px}.actions{margin-left:auto;display:flex;gap:8px}button{font:inherit}button.action{border:1px solid #e8ded8;background:#fff;border-radius:12px;padding:11px;cursor:pointer;color:#5d4037}button.action:hover{background:#f6efeb}.messages{flex:1;overflow:auto;padding:24px;display:flex;flex-direction:column;gap:12px}.bubble{max-width:min(75%,550px);background:white;padding:12px 16px;border-radius:17px 17px 17px 4px;box-shadow:0 2px 9px #00000008;white-space:pre-wrap;overflow-wrap:anywhere}.bubble.mine{align-self:flex-end;background:#5d4037;color:white;border-radius:17px 17px 4px 17px}.time{font-size:10px;opacity:.65;margin-top:7px}.empty{margin:auto;text-align:center;color:#96857b;line-height:1.8}.empty b{font-size:21px;color:#60483d}.compose{padding:15px 20px;background:#fff;border-top:1px solid #e9e3df;display:flex;gap:10px}.compose textarea{resize:none;flex:1;min-width:0;border:1px solid #e7ddd7;border-radius:13px;padding:12px;font:inherit;height:47px}.send{background:#5d4037;color:white;border:0;border-radius:12px;padding:0 22px;cursor:pointer}.send:disabled{opacity:.45;cursor:default}.notice{padding:10px 20px;background:#fff3e6;color:#8c4e1d;display:none}.callbox{position:fixed;inset:0;background:#161312ee;z-index:10;display:none;flex-direction:column;align-items:center;justify-content:center;color:white;gap:15px}.videos{display:flex;gap:12px;width:min(900px,94vw);height:min(55vh,500px)}video{background:#27211f;border-radius:16px;width:50%;object-fit:cover}.callbox button{border:0;border-radius:25px;padding:12px 23px;cursor:pointer}.hang{background:#d74646;color:white}.accept{background:#4c956c;color:white}.callcontrols{display:flex;gap:12px}@media(max-width:650px){.app{grid-template-columns:105px 1fr}.brand{font-size:13px;padding:15px 8px}.sub,.search,.hint,.count{display:none}.uname{display:block;font-size:10px;overflow:hidden;text-overflow:ellipsis;max-width:70px}.user{flex-direction:column;gap:3px}.user{justify-content:center;padding:10px 4px}.head{padding:12px}.messages{padding:12px}.bubble{max-width:90%}.compose{padding:9px}.send{padding:0 12px}.videos{flex-direction:column}.videos video{width:100%;height:50%}}
</style></head><body><div class="app"><aside class="side"><div class="brand">💬 Messages<div class="sub">Connect with your team</div></div><input class="search" id="search" placeholder="Search colleagues…" aria-label="Search colleagues"><div class="users" id="users"></div></aside><main class="main"><header class="head"><span class="avatar" id="headAvatar">✦</span><div><strong id="headName">Team conversations</strong><div class="hint" id="headStatus">Choose a colleague to begin</div></div><div class="actions"><button class="action" id="audio" title="Audio call" disabled>☎ Audio</button><button class="action" id="video" title="Video call" disabled>▣ Video</button></div></header><div class="notice" id="notice"<?=isset($startupError)?' style="display:block"':''?>><?=isset($startupError)?htmlspecialchars($startupError,ENT_QUOTES,'UTF-8'):''?></div><div class="messages" id="messages"><div class="empty"><b>Conversations made simple</b><div>Private messaging, voice and video calls<br>for your coffee sales team.</div></div></div><form class="compose" id="compose"><textarea id="body" placeholder="Write a message…" aria-label="Message" disabled></textarea><button class="send" id="send" disabled>Send ➤</button></form></main></div><div class="callbox" id="callbox"><h2 id="calltitle">Calling…</h2><div class="videos"><video id="remote" autoplay playsinline></video><video id="local" autoplay muted playsinline></video></div><div class="callcontrols"><button class="accept" id="accept" style="display:none">Answer</button><button id="mute">Mute</button><button id="camera">Camera off</button><button class="hang" id="hang">End call</button></div></div><script>
const csrf=<?=json_encode($chatCsrf??'')?>;let me=<?=json_encode($me??null)?>,selected=null,users=[],lastMessages='',currentCall=null,pc=null,stream=null,lastSignal=0,pendingCandidates=[],answering=false;
const $=id=>document.getElementById(id);const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(action,data=null,params=''){const r=await fetch('messages.php?action='+action+params,{method:data?'POST':'GET',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:data?JSON.stringify(data):undefined,cache:'no-store'});const j=await r.json();if(!r.ok)throw Error(j.error||'Request failed');return j}
function notify(s){$('notice').textContent=s;$('notice').style.display='block';setTimeout(()=>$('notice').style.display='none',5500)}
async function refreshUsers(){try{const d=await api('users');users=d.users;const term=$('search').value.toLowerCase();$('users').innerHTML=users.filter(u=>u.display_name.toLowerCase().includes(term)).map(u=>`<button class="user ${selected===+u.id?'selected':''}" data-id="${u.id}"><span class="avatar">${escapeHTML(u.display_name[0]?.toUpperCase()||'?')}</span><span><span class="uname">${escapeHTML(u.display_name)}</span><span class="hint">${u.last_seen && Date.now()-Date.parse(u.last_seen)<90000?'Active recently':'Team member'}</span></span>${+u.unread?`<span class="count">${u.unread}</span>`:''}</button>`).join('')||'<div class="hint" style="padding:20px">No other users have opened Messages yet.</div>';document.querySelectorAll('.user').forEach(b=>b.onclick=()=>selectUser(+b.dataset.id));}catch(e){notify(e.message)}}
function selectUser(id){selected=id;const u=users.find(x=>+x.id===id);$('headName').textContent=u?.display_name||'Colleague';$('headAvatar').textContent=(u?.display_name||'?')[0].toUpperCase();$('headStatus').textContent='Private conversation';['audio','video','body','send'].forEach(k=>$(k).disabled=false);lastMessages='';refreshUsers();refreshMessages()}
async function refreshMessages(){if(!selected)return;const recipient=selected;try{const d=await api('messages',null,'&user='+recipient);if(selected!==recipient)return;const key=JSON.stringify(d.messages);if(key===lastMessages)return;lastMessages=key;const el=$('messages'),atBottom=el.scrollHeight-el.scrollTop-el.clientHeight<100;el.innerHTML=d.messages.length?d.messages.map(m=>`<div class="bubble ${+m.sender_id===me?'mine':''}">${escapeHTML(m.body)}<div class="time">${new Date(m.created_at).toLocaleString()}</div></div>`).join(''):'<div class="empty">No messages yet. Say hello 👋</div>';if(atBottom||d.messages.length<3)el.scrollTop=el.scrollHeight;}catch(e){notify(e.message)}}
$('search').oninput=refreshUsers;$('compose').onsubmit=async e=>{e.preventDefault();const body=$('body').value.trim();if(!body||!selected)return;try{$('send').disabled=true;await api('send',{user:selected,body});$('body').value='';await refreshMessages()}catch(e){notify(e.message)}finally{$('send').disabled=!selected}};$('body').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('compose').requestSubmit()}};
async function media(kind){stream=await navigator.mediaDevices.getUserMedia({audio:true,video:kind==='video'});$('local').srcObject=stream;$('local').style.display=kind==='video'?'block':'none';$('camera').style.display=kind==='video'?'':'none';pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});stream.getTracks().forEach(t=>pc.addTrack(t,stream));pc.ontrack=e=>$('remote').srcObject=e.streams[0];pc.onicecandidate=e=>{if(e.candidate&&currentCall)api('signal',{call:currentCall.id,payload:{type:'candidate',candidate:e.candidate}}).catch(console.error)};$('callbox').style.display='flex'}
async function startCall(kind){if(!selected||currentCall)return;try{const c=await api('call',{user:selected,kind});currentCall={id:c.id,kind,caller_id:me,callee_id:selected,status:'ringing'};lastSignal=0;$('calltitle').textContent='Calling…';$('accept').style.display='none';await media(kind);const offer=await pc.createOffer();await pc.setLocalDescription(offer);await api('signal',{call:c.id,payload:{type:'offer',sdp:offer}})}catch(e){notify(e.message);await endCall()}}
async function acceptCall(){if(!currentCall)return;try{answering=true;await media(currentCall.kind);await api('status',{call:currentCall.id,status:'active'});$('accept').style.display='none';$('calltitle').textContent='Connected';await pollSignals()}catch(e){notify(e.message);await endCall()}}
async function endCall(){const id=currentCall?.id;currentCall=null;answering=false;lastSignal=0;pendingCandidates=[];if(pc){pc.close();pc=null}if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}$('remote').srcObject=null;$('local').srcObject=null;$('callbox').style.display='none';$('accept').style.display='none';if(id)try{await api('status',{call:id,status:'ended'})}catch(e){}}
async function pollSignals(){if(!currentCall)return;const d=await api('signals',null,'&call='+currentCall.id+'&after='+lastSignal);if(['ended','declined'].includes(d.status)){await endCall();return}for(const s of d.signals){lastSignal=Math.max(lastSignal,+s.id);const p=s.payload;if(p.type==='offer'&&pc){await pc.setRemoteDescription(p.sdp);const ans=await pc.createAnswer();await pc.setLocalDescription(ans);await api('signal',{call:currentCall.id,payload:{type:'answer',sdp:ans}})}else if(p.type==='answer'&&pc&&!pc.currentRemoteDescription){await pc.setRemoteDescription(p.sdp)}else if(p.type==='candidate'){if(pc?.remoteDescription)await pc.addIceCandidate(p.candidate);else pendingCandidates.push(p.candidate)}}if(pc?.remoteDescription){for(const c of pendingCandidates.splice(0))await pc.addIceCandidate(c)}}
async function refreshCalls(){try{if(!currentCall){const d=await api('calls');const incoming=d.calls.find(c=>+c.callee_id===me&&c.status==='ringing');if(incoming){currentCall=incoming;lastSignal=0;$('callbox').style.display='flex';$('calltitle').textContent=(incoming.caller_name||'Colleague')+' is calling ('+incoming.kind+')';$('accept').style.display='';$('local').style.display='none';$('camera').style.display='none';}}else if(pc)await pollSignals();else{const d=await api('calls');if(!d.calls.some(c=>+c.id===+currentCall.id))await endCall();}}catch(e){console.warn(e)}}
$('audio').onclick=()=>startCall('audio');$('video').onclick=()=>startCall('video');$('accept').onclick=acceptCall;$('hang').onclick=endCall;$('mute').onclick=()=>{if(!stream)return;const t=stream.getAudioTracks()[0];if(t){t.enabled=!t.enabled;$('mute').textContent=t.enabled?'Mute':'Unmute'}};$('camera').onclick=()=>{const t=stream?.getVideoTracks()[0];if(t){t.enabled=!t.enabled;$('camera').textContent=t.enabled?'Camera off':'Camera on'}};
refreshUsers();setInterval(()=>{if(!document.hidden){refreshUsers();refreshMessages();refreshCalls()}},2500);refreshCalls();
</script></body></html>
